Widget buildJumpGlyph(String playingPath) => glyphButton(
  semanticsLabel: 'jump to now-playing folder',
  buttonKey: const ValueKey('void-crumb-jump-to-playing'),
  onTap: () => jumpToNowPlaying(playingPath),
  box: 44,
  glyph: '⊙', // ⊙ — CIRCLED DOT OPERATOR
  style: mono(palette.fgPrimary, typography.rowSize, height: 1),
);

// B-XYZ: on Linux, offer an explicit accessible action when the now-
// playing track is in the current folder but currently offscreen.
Widget buildJumpToTrackGlyph(String playingPath) => glyphButton(
  semanticsLabel: 'jump to now-playing track',
  buttonKey: const ValueKey('void-crumb-jump-to-playing-track'),
  onTap: () => jumpToNowPlaying(playingPath),
  box: 44,
  glyph: '◎', // ◎ — circled ring (distinct from the folder jump glyph)
  style: mono(palette.fgPrimary, typography.rowSize, height: 1),
);

